import{_ as c,C as i,o as d,c as s,j as o,a as t,b as l,w as r,E as n,a3 as P,a2 as p}from"./chunks/framework.CWWEQfK7.js";const B=JSON.parse('{"title":"按模块配置五个服务","description":"按职责配置 Ershu 的 Core、API、Worker、MCP 和前端，并确认各进程连接正确。","frontmatter":{"page_id":"configuration-services","description":"按职责配置 Ershu 的 Core、API、Worker、MCP 和前端，并确认各进程连接正确。"},"headers":[],"relativePath":"configuration/services.md","filePath":"configuration/services.md","lastUpdated":1786290726000}'),h={name:"configuration/services.md"};function A(u,e,E,C,_,k){const a=i("Mermaid");return d(),s("div",null,[e[1]||(e[1]=o("h1",{id:"按模块配置五个服务",tabindex:"-1"},[t("按模块配置五个服务 "),o("a",{class:"header-anchor",href:"#按模块配置五个服务","aria-label":'Permalink to "按模块配置五个服务"'},"​")],-1)),e[2]||(e[2]=o("p",null,"Ershu 由五个独立模块组成。它们共享数据约定，但不是五个都要启动：Core 是共享包，另外四个模块才有运行中的进程或网页。",-1)),(d(),l(P,null,{default:r(()=>[n(a,{id:"mermaid-6",class:"ershu-mermaid",graph:"flowchart%20LR%0A%20%20Browser%5B%22%E6%B5%8F%E8%A7%88%E5%99%A8%22%5D%20--%3E%20Frontend%5B%22Frontend%22%5D%0A%20%20Frontend%20--%3E%7C%22%2Fapi%2Fv1%22%7C%20API%5B%22API%22%5D%0A%20%20Client%5B%22MCP%20%E5%AE%A2%E6%88%B7%E7%AB%AF%22%5D%20--%3E%7C%22%2Fmcp%2F%22%7C%20MCP%5B%22MCP%22%5D%0A%20%20API%20--%3E%20Core%5B%22Core%20%E5%85%B1%E4%BA%AB%E8%83%BD%E5%8A%9B%22%5D%0A%20%20MCP%20--%3E%20Core%0A%20%20Worker%5B%22Worker%22%5D%20--%3E%20Core%0A%20%20API%20--%3E%20PG%5B(PostgreSQL)%5D%0A%20%20Worker%20--%3E%20PG%0A%20%20MCP%20--%3E%20PG%0A%20%20API%20--%3E%20Milvus%5B(Milvus)%5D%0A%20%20Worker%20--%3E%20Milvus%0A%20%20MCP%20--%3E%20Milvus%0A%20%20API%20--%3E%7C%22%E5%86%99%E5%85%A5%E4%BB%BB%E5%8A%A1%22%7C%20Queue%5B%22PostgreSQL%20%E4%BB%BB%E5%8A%A1%E9%98%9F%E5%88%97%22%5D%0A%20%20Queue%20--%3E%7C%22%E9%A2%86%E5%8F%96%E4%BB%BB%E5%8A%A1%22%7C%20Worker%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=p('<p>API、Worker 和 MCP 都只依赖 Core。Worker 与 MCP 不直接调用 API，也不互相调用；它们通过 PostgreSQL 中的项目、任务和索引状态协作。</p><h2 id="模块职责和启动边界" tabindex="-1">模块职责和启动边界 <a class="header-anchor" href="#模块职责和启动边界" aria-label="Permalink to &quot;模块职责和启动边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>负责什么</th><th>启动入口</th><th>默认地址</th><th>可观察的就绪信号</th></tr></thead><tbody><tr><td>Core</td><td>设置、数据模型、数据库迁移、权限、仓库访问和共享查询</td><td>不启动服务；迁移入口是 <code>ershu-db</code></td><td>无</td><td>数据库迁移命令以退出码 <code>0</code> 结束</td></tr><tr><td>API</td><td>网页登录、项目与仓库管理、运行、文档、搜索、聊天和管理接口</td><td><code>uv run ershu-api</code></td><td><code>127.0.0.1:8000</code></td><td><code>/health</code> 返回 <code>status: ok</code>；依赖检查见下文</td></tr><tr><td>Worker</td><td>领取任务，准备只读工作区，建立目录、代码索引、关系和搜索索引，并生成文档</td><td><code>uv run ershu-worker</code></td><td>无监听端口</td><td>进程持续运行；排队任务开始推进</td></tr><tr><td>MCP</td><td>向开发智能体提供受权限约束的只读工具</td><td><code>uv run ershu-mcp</code></td><td><code>127.0.0.1:8001/mcp/</code></td><td>认证后调用 <code>get_server_info</code>，返回版本、构建提交和工具列表</td></tr><tr><td>Frontend</td><td>提供浏览器界面，只通过已发布的 HTTP 接口访问后端</td><td><code>npm run dev</code></td><td><code>localhost:3000</code></td><td>首次管理员设置页或登录页能够打开，且没有持续网络错误</td></tr></tbody></table><p>API 仓库还提供独立的 <code>ershu-api-poller</code> 进程，用于执行仓库的 UTC Cron 计划。它不是 API Web 进程的一部分，也不代替 Worker。</p><h2 id="共享值必须保持一致" tabindex="-1">共享值必须保持一致 <a class="header-anchor" href="#共享值必须保持一致" aria-label="Permalink to &quot;共享值必须保持一致&quot;">​</a></h2><p>独立运行各模块时，每个进程从自己的环境读取设置。组合部署可以使用 <code>ershu/.env.example</code> 作为后端配置全集，但每个模块只消费自己认识的字段。</p><p>以下值不能在进程之间随意分叉：</p><ul><li>API、Worker 和 MCP 必须连接同一套 PostgreSQL，任务和项目状态才能互相可见。</li><li>需要向量检索时，API、Worker 和 MCP 应连接同一 Milvus 数据库。</li><li>Worker 的 <code>ENCRYPTION_KEY</code> 必须与写入加密凭据和模型密钥的 API 一致；MCP 读取受保护凭据时也使用同一值。</li><li>API 与 MCP 的 <code>SECRET_KEY</code>、<code>ENCRYPTION_KEY</code> 和 <code>MCP_KEY_PEPPER</code> 都必须是至少 32 个字符的强值，三者彼此不同；两项服务之间应使用相同的一组值。</li><li>模型通道保存在数据库中，由网页管理后台或 API 管理，不写入 <code>.env</code>。</li></ul><p>完整字段、默认值和范围见<a href="./environment-reference">环境变量参考</a>。</p><h2 id="仓库工作区怎样分配" tabindex="-1">仓库工作区怎样分配 <a class="header-anchor" href="#仓库工作区怎样分配" aria-label="Permalink to &quot;仓库工作区怎样分配&quot;">​</a></h2><p>远程 Git 仓库不要求 MCP 与 Worker 共用缓存。两个进程都能按登记的远程地址准备自己的只读工作区，<code>REPOSITORY_STORAGE_PATH</code> 可以指向各自主机上的缓存目录。</p><p>本地仓库不同：登记的路径不会被复制到另一台主机。Worker 要分析它、MCP 要读取它，这两个进程就都必须能看到同一路径，并且该路径要在 <code>TRUSTED_LOCAL_PATHS</code> 允许范围内。生产环境不能用 <code>ALLOW_DEV_OPEN_LOCAL_REPOSITORY_PATHS</code> 绕过这项限制。</p><h2 id="推荐启动顺序" tabindex="-1">推荐启动顺序 <a class="header-anchor" href="#推荐启动顺序" aria-label="Permalink to &quot;推荐启动顺序&quot;">​</a></h2><p>以下是根据当前入口整理的操作顺序，未在你的机器上代为执行：</p><ol><li>启动 PostgreSQL、Redis 和 Milvus 等基础设施。</li><li>用 Core 提供的迁移入口升级数据库。</li><li>启动 API，检查 <code>/api/v1/health/dependencies</code>。响应中的 <code>database.ok</code> 和 <code>milvus.ok</code> 都应为 <code>true</code>。这个检查不包含 Redis。</li><li>启动 Worker，确认它没有因密钥、数据库或结构化解析器自检失败而退出。</li><li>启动 Frontend，完成管理员和模型通道配置。</li><li>需要开发智能体接入时再启动 MCP；需要定时检查仓库时再启动 Poller。</li></ol><p>API 和 MCP 的 <code>/health</code> 都只是进程存活信号。MCP 是否真正可用，要以带凭据调用 <code>get_server_info</code> 为准；Worker 是否可用，要以任务能被领取和推进为准。</p><h2 id="反向代理要分开转发" tabindex="-1">反向代理要分开转发 <a class="header-anchor" href="#反向代理要分开转发" aria-label="Permalink to &quot;反向代理要分开转发&quot;">​</a></h2><p>生产代理应保留原始路径，并将两个前缀发送到不同进程：</p><table tabindex="0"><thead><tr><th>路径</th><th>目标</th></tr></thead><tbody><tr><td><code>/api/</code></td><td>API 的 <code>8000</code> 端口</td></tr><tr><td><code>/mcp/</code></td><td>MCP 的 <code>8001</code> 端口</td></tr></tbody></table><p>前端默认使用同源 <code>/api/v1</code>。不要把 <code>/mcp/</code> 发到 API 端口。代理终止 HTTPS 时，还要把实际的 Host 和 <code>X-Forwarded-Proto</code> 传给后端，并按代理来源设置 <code>FORWARDED_ALLOW_IPS</code>。MCP 的外部域名和来源还要加入 <code>MCP_ALLOWED_HOSTS</code> 与 <code>MCP_ALLOWED_ORIGINS</code>。</p><blockquote><p>主要源码位置：<code>core/src/ershu/core/config.py</code>、<code>api/src/ershu/api_main.py</code>、<code>api/src/ershu/api/poller.py</code>、<code>worker/src/ershu/workers/analysis.py</code>、<code>mcp/src/ershu/mcp_main.py</code>、<code>frontend/vite.config.ts</code>。</p></blockquote>',21))])}const M=c(h,[["render",A]]);export{B as __pageData,M as default};
